CREATE TYPE "analytics_error_code" AS ENUM ('VALIDATION_ERROR', 'BAD_REQUEST', 'NOT_FOUND', 'CONFLICT', 'PAYLOAD_TOO_LARGE', 'UNSUPPORTED_MEDIA_TYPE', 'METHOD_NOT_ALLOWED', 'UNAUTHORIZED', 'BAD_GATEWAY', 'SERVICE_UNAVAILABLE', 'INTERNAL_ERROR', 'VOICE_CONFIG_ERROR', 'VOICE_PROVIDER_UNAVAILABLE', 'VOICE_SESSION_ERROR', 'VOICE_INVALID_MESSAGE', 'VOICE_TOOL_ERROR', 'VOICE_LIMIT_REACHED', 'UNKNOWN_TOOL', 'INVALID_ARGUMENTS', 'TOOL_FAILED', 'TOOL_LIMIT_REACHED');

