-- ---------------------------------------------------------------------------------------------
-- CHECK constraints (hand-written): each optional field only where it has a meaning, so rows
-- cannot carry misplaced data.
-- ---------------------------------------------------------------------------------------------

ALTER TABLE "analytics_events"
    -- Integer milliseconds, 0 to 24 hours.
    ADD CONSTRAINT "analytics_events_duration_range_check" CHECK ("duration_ms" IS NULL OR ("duration_ms" >= 0 AND "duration_ms" <= 86400000)),
    -- A controlled error code describes a failure only.
    ADD CONSTRAINT "analytics_events_error_only_on_failure_check" CHECK ("error_code" IS NULL OR NOT "success"),
    -- ScamShield fields only on ScamShield analyses, which always name the content type.
    ADD CONSTRAINT "analytics_events_scam_fields_check" CHECK (
        ("event_type" = 'SCAM_ANALYSIS' AND "scam_source_type" IS NOT NULL)
        OR ("event_type" <> 'SCAM_ANALYSIS' AND "scam_source_type" IS NULL AND "scam_risk_level" IS NULL)
    ),
    -- Tool names only on tool calls and calculations; a calculation always names its calculator.
    -- (A tool call may lack a name when the model requested a tool that is not on the allowlist.)
    ADD CONSTRAINT "analytics_events_tool_name_check" CHECK (
        ("event_type" = 'CALCULATION' AND "tool_name" IS NOT NULL)
        OR "event_type" IN ('AGENT_TOOL_CALL', 'VOICE_TOOL_CALL')
        OR ("event_type" NOT IN ('CALCULATION', 'AGENT_TOOL_CALL', 'VOICE_TOOL_CALL') AND "tool_name" IS NULL)
    ),
    -- Knowledge categories only on knowledge and literacy events; literacy events always have one.
    ADD CONSTRAINT "analytics_events_knowledge_category_check" CHECK (
        ("event_type" IN ('LITERACY_TOPIC_STARTED', 'LITERACY_TOPIC_COMPLETED') AND "knowledge_category" IS NOT NULL)
        OR "event_type" IN ('KNOWLEDGE_SEARCH', 'KNOWLEDGE_ARTICLE_VIEW')
        OR ("event_type" NOT IN ('LITERACY_TOPIC_STARTED', 'LITERACY_TOPIC_COMPLETED', 'KNOWLEDGE_SEARCH', 'KNOWLEDGE_ARTICLE_VIEW') AND "knowledge_category" IS NULL)
    ),
    -- The random voice-session id only on voice sessions.
    ADD CONSTRAINT "analytics_events_session_id_check" CHECK ("session_id" IS NULL OR "event_type" = 'VOICE_SESSION');
